package com.djibtout.backend.entity;import jakarta.persistence.*;import java.time.*;
@Entity public class AuditLog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne private User actor;private String action;@Column(length=500)private String target;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public User getActor(){return actor;}public void setActor(User v){actor=v;}public String getAction(){return action;}public void setAction(String v){action=v;}public String getTarget(){return target;}public void setTarget(String v){target=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
